const tabId = 725789952;

const parkingText = await browserjs(tabId, () => {
  const allElements = Array.from(document.querySelectorAll('*'));
  const matches = [];
  for (const el of allElements) {
    if (el.children.length === 0 && el.textContent.toLowerCase().includes('parking')) {
      // get surrounding paragraph or parent text
      let p = el.parentElement;
      for (let i = 0; i < 3 && p; i++) {
        if (p.textContent.length > el.textContent.length + 10) {
          matches.push(p.textContent.trim().replace(/\s+/g, ' '));
          break;
        }
        p = p.parentElement;
      }
      if (!matches.length || !matches[matches.length - 1].includes(el.textContent.trim())) {
        matches.push(el.textContent.trim());
      }
    }
  }
  return Array.from(new Set(matches)).slice(0, 15);
});

