    // Find all blocks containing "Parking"
    const blocks = Array.from(document.querySelectorAll('div, li, p, section')).map(e => e.innerText?.trim()).filter(Boolean);
    const specificParking = blocks.filter(b => 
      b.startsWith("Parking") || 
      (b.toLowerCase().includes("parking") && (b.includes("USD") || b.includes("$") || b.toLowerCase().includes("free") || b.toLowerCase().includes("reservation")))
    );
    // Find shortest matching text that describes parking
    const cleanMatches = specificParking.sort((a,b) => a.length - b.length).slice(0, 3);
    return {
      title: document.title,
      matches: cleanMatches
    };
  });
  parkingDetails.push({ tabId: t, ...res });
}

