const tabId = 725789951;

const cardData = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('[data-testid="property-card"]'));
  return cards.map((c, i) => {
    const titleEl = c.querySelector('[data-testid="title"]');
    const title = titleEl?.textContent?.trim() || "";
    const linkEl = c.querySelector('a[data-testid="title-link"]') || c.querySelector('a[href*="/hotel/"]');
    const href = linkEl?.href || "";

    const addressEl = c.querySelector('[data-testid="address"]');
    const address = addressEl?.textContent?.trim() || "";

    const distanceEl = c.querySelector('[data-testid="distance"]');
    const distance = distanceEl?.textContent?.trim() || "";

    const ratingEl = c.querySelector('[data-testid="review-score"]');
    const ratingText = ratingEl?.textContent?.trim() || "";

    const priceEl = c.querySelector('[data-testid="price-and-discounted-price"]');
    const priceText = priceEl?.textContent?.trim() || "";

    // Charges/taxes/fees
    const chargesEl = c.querySelector('[data-testid="taxes-and-charges"]');
    const chargesText = chargesEl?.textContent?.trim() || "";

    // Cancellation policy
    const cancellationEl = c.querySelector('[data-testid="cancellation-policy"]');
    const cancellationText = cancellationEl?.textContent?.trim() || "";

    // Entire text of card to check for parking, resort fee, cancellation, etc.
    const allText = c.innerText;

    return {
      index: i + 1,
      title,
      href,
      address,
      distance,
      ratingText,
      priceText,
      chargesText,
      cancellationText,
      allTextSnippet: allText.split("\n").filter(l => l.trim().length > 0)
    };
  });
});

