    const cancelPolicy = cancelLine || "not shown";

    // Check for parking info
    const parkingLine = textLines.find(l => l.toLowerCase().includes("parking"));
    const parkingPolicy = parkingLine || "not shown";

    // Check for resort fee info
    const feeLine = textLines.find(l => l.toLowerCase().includes("resort fee") || l.toLowerCase().includes("taxes and charges"));
    const feePolicy = feeLine || "not shown";

    return {
      index: i + 1,
      title,
      href,
      address,
      distance,
      ratingText,
      priceText,
      cancelPolicy,
      parkingPolicy,
      feePolicy,
      summaryLines: textLines
    };
