const openedTabs = JSON.parse(await (await read("tmp://opened_listing_tabs.json")).text);

const results = [];

for (const t of openedTabs) {
  console.log(`Analyzing tab ${t.tabId}: ${t.hotelName}...`);
  try {
    await tool.wait_for({ tabId: t.tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
    await tool.wait_for({ tabId: t.tabId, condition: "dom_settled", timeout_ms: 3000 });

    const data = await browserjs(t.tabId, () => {
      // Extract title/address
      const address = document.querySelector('[data-node_tt_id="location_header_address"]')?.textContent?.trim() ||
                      document.querySelector('.hp_address_subtitle')?.textContent?.trim() ||
                      document.querySelector('[data-testid="PropertyHeaderAddress"]')?.textContent?.trim() || "";

      // Rating & review count
      const rating = document.querySelector('[data-testid="review-score-right-component"]')?.innerText?.replace(/\n+/g, ' ') ||
                     document.querySelector('.b5cd09854e')?.textContent?.trim() || "";

      // Facilities / amenities
      const facilities = Array.from(document.querySelectorAll('[data-testid="property-most-popular-facilities-wrapper"] li, .hp_desc_important_facilities li'))
        .map(el => el.textContent?.trim()).filter(Boolean);

      // Look for parking & resort fee in the page text
      const fullText = document.body.innerText;

      // Parking extraction
      let parkingInfo = "not shown";
      const parkingMatch = fullText.match(/(?:Public|Private|Self|Valet)?\s*[Pp]arking\s*(?:is available|is possible|on site|costs)?[^\.\n]*/i);
      // Look for section around parking
      const parkingSection = Array.from(document.querySelectorAll('div, p, span, li'))
        .map(el => el.innerText)
        .find(txt => txt && txt.includes("Parking") && (txt.includes("USD") || txt.includes("per day") || txt.includes("free") || txt.includes("Free") || txt.includes("cost")));

      // Resort fee extraction
      let resortFeeInfo = "not shown";
      const feeMatch = fullText.match(/(?:Resort fee|resort fee|destination fee|service charge)[^\.\n]*/i);
      if (feeMatch) resortFeeInfo = feeMatch[0];

      // Price breakdown
      const priceElement = document.querySelector('.prco-valign-middle-helper') ||
                           document.querySelector('[data-testid="price-and-discounted-price"]') ||
                           document.querySelector('.bui-price-display__value');
      const price = priceElement?.textContent?.trim() || "";

      // Cancellation policy
      const cancellationSection = Array.from(document.querySelectorAll('.bui-alert, .rt-cancellation-policy, [data-testid="cancellation-policy"]'))
        .map(el => el.innerText.trim()).filter(Boolean).join(" | ");

      // Photos info
      const photosCount = document.querySelectorAll('img[src*="hotel"], [data-testid="gallery-side-image"] img').length;

      return {
        address,
        rating,
        facilities: facilities.slice(0, 8),
        parkingSection: parkingSection ? parkingSection.slice(0, 200) : "not shown",
        parkingMatch: parkingMatch ? parkingMatch[0] : "not shown",
        resortFeeInfo,
        price,
        cancellationSection: cancellationSection || "not shown",
        photosCount,
        snippet: fullText.slice(0, 500)
      };
    });

    results.push({ ...t, data });
  } catch (err) {
    console.error(`Error analyzing tab ${t.tabId}:`, err.message);
    results.push({ ...t, error: err.message });
  }
}

await write("tmp://listing_inspections.json", JSON.stringify(results, null, 2), "application/json");
console.log("Inspection complete. Saved to tmp://listing_inspections.json");
for (const r of results) {
  console.log(`=== ${r.hotelName} ===`);
  console.log(`Address: ${r.data?.address}`);
  console.log(`Rating: ${r.data?.rating}`);
