const allOpened = [
  { tabId: 725789952, name: "SpringHill Suites by Marriott Orlando at FLAMINGO CROSSINGS Town Center-Western Entrance" },
  { tabId: 725789953, name: "Home2 Suites By Hilton Orlando Flamingo Crossings, FL" },
  { tabId: 725789954, name: "Homewood Suites By Hilton Orlando Flamingo Crossings, Fl" },
  { tabId: 725789955, name: "Fairfield Inn & Suites, Lake Buena Vista - Orlando Marriott Village" },
  { tabId: 725789956, name: "Sonesta ES Suites Orlando - Lake Buena Vista" },
  { tabId: 725789957, name: "Holiday Inn & Suites Orlando SW - Celebration Area by IHG" },
  { tabId: 725789958, name: "Wyndham Garden Lake Buena Vista – Disney Springs® Area" },
  { tabId: 725789959, name: "TownePlace Suites Orlando at FLAMINGO CROSSINGS Town Center, Western Entrance" },
  { tabId: 725789960, name: "Holiday Inn Orlando – Disney Springs® Area by IHG" },
  { tabId: 725789961, name: "Holiday Inn Resort Orlando - Lake Buena Vista by IHG" },
  { tabId: 725789962, name: "Delta Hotels by Marriott Orlando Celebration" },
  { tabId: 725789963, name: "Ramada by Wyndham Kissimmee Gateway - Free Theme Park Shuttle" }
];

const extractedHotels = [];

for (const item of allOpened) {
  try {
    await tool.wait_for({ tabId: item.tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
    await tool.wait_for({ tabId: item.tabId, condition: "dom_settled", timeout_ms: 3000 });

    const data = await browserjs(item.tabId, () => {
      // JSON-LD
      const scripts = Array.from(document.querySelectorAll('script[type="application/ld+json"]'));
      let jsonLd = null;
      for (const s of scripts) {
        try {
          const parsed = JSON.parse(s.innerText);
          if (parsed["@type"] === "Hotel" || parsed.name) {
            jsonLd = parsed;
            break;
          }
        } catch (e) {}
      }

      // Ratings & Reviews
      const scoreEl = document.querySelector('[data-testid="review-score-right-component"]') || document.querySelector('.b5cd09854e');
      const scoreText = scoreEl ? scoreEl.innerText.replace(/\n+/g, ' ') : null;

      // Price & fees
      const priceText = document.querySelector('.prco-valign-middle-helper, [data-testid="price-and-discounted-price"], .bui-price-display__value')?.textContent?.trim();

      const fullText = document.body.innerText;

      // Resort fee search
      const feeMatches = fullText.match(/(?:Included:\s*)?\$?\d+(?:\.\d+)?\s*(?:Resort fee|resort fee|destination fee|service charge)[^\.\n]*/gi) || [];

      // Parking search
      const parkingMatches = [];
      const lines = fullText.split('\n').map(l => l.trim()).filter(Boolean);
      for (const line of lines) {
        if (/parking/i.test(line) && (/free/i.test(line) || /usd|\$|\/day|per day|available|on site|valet/i.test(line))) {
          parkingMatches.push(line);
        }
      }

      // Cancellation search
      const cancellationMatches = [];
      for (const line of lines) {
        if (/free cancellation|non-refundable|refundable|cancellation policy/i.test(line)) {
          cancellationMatches.push(line);
        }
      }

      // Amenities
      const facilities = Array.from(document.querySelectorAll('[data-testid="property-most-popular-facilities-wrapper"] li, .hp_desc_important_facilities li'))
        .map(el => el.textContent?.trim()).filter(Boolean);

      // Photos
      const images = Array.from(document.querySelectorAll('img[src*="hotel"]')).map(i => i.src);

      return {
        name: jsonLd?.name || document.title,
        streetAddress: jsonLd?.address?.streetAddress || jsonLd?.address?.addressLocality || null,
        ratingValue: jsonLd?.aggregateRating?.ratingValue || null,
        reviewCount: jsonLd?.aggregateRating?.reviewCount || null,
        scoreText,
        priceText,
        feeMatches: Array.from(new Set(feeMatches)).slice(0, 3),
        parkingMatches: Array.from(new Set(parkingMatches)).slice(0, 5),
        cancellationMatches: Array.from(new Set(cancellationMatches)).slice(0, 5),
        facilities: facilities.slice(0, 10),
        imagesCount: images.length,
        sampleImages: images.slice(0, 3)
      };
    });

    extractedHotels.push({ tabId: item.tabId, initialName: item.name, ...data });
  } catch (err) {
    console.error(`Error on tab ${item.tabId}:`, err.message);
    extractedHotels.push({ tabId: item.tabId, initialName: item.name, error: err.message });
  }
}

await write("tmp://extracted_12_hotels.json", JSON.stringify(extractedHotels, null, 2), "application/json");
console.log("Successfully extracted data for all 12 hotels!");
for (const h of extractedHotels) {
  console.log(`[Tab ${h.tabId}] ${h.name}`);
  console.log(`  Address: ${h.streetAddress}`);
  console.log(`  Rating: ${h.ratingValue} (${h.reviewCount} reviews) | Price: ${h.priceText}`);
  console.log(`  Resort fee: ${h.feeMatches.join('; ') || 'none shown'}`);
  console.log(`  Parking: ${h.parkingMatches.join('; ') || 'none shown'}`);
  console.log(`  Cancellation: ${h.cancellationMatches[0] || 'not shown'}`);
}

