  { id: 4, name: "Homewood Suites Flamingo Crossings", address: "411 Flagler Ave, Orlando, FL 34787" },
  { id: 5, name: "Wyndham Garden Disney Springs", address: "1850 B Hotel Plaza Boulevard, Lake Buena Vista, FL 32830" },
  { id: 6, name: "Fairfield Inn Marriott Village LBV", address: "8615 Vineland Avenue, Lake Buena Vista, FL 32821" },
  { id: 7, name: "Sonesta ES Suites LBV", address: "8751 Suiteside Drive, Lake Buena Vista, FL 32836" },
  { id: 8, name: "Holiday Inn Disney Springs Area", address: "1805 Hotel Plaza Boulevard, Lake Buena Vista, FL 32830" },
  { id: 9, name: "Holiday Inn Resort LBV", address: "13351 State Road 535, Lake Buena Vista, FL 32821" },
  { id: 10, name: "Holiday Inn & Suites Celebration", address: "5711 W Irlo Bronson Memorial Hwy, Kissimmee, FL 34746" },
  { id: 11, name: "Delta Hotels Celebration", address: "2900 Parkway Boulevard, Kissimmee, FL 34747" },
  { id: 12, name: "Ramada Kissimmee Gateway", address: "7470 W Irlo Bronson Memorial Hwy, Kissimmee, FL 34747" }
];

const mapResults = [];

for (const h of hotels) {
  console.log(`Checking Maps for: ${h.name}...`);
  const origin = encodeURIComponent(h.address);
  const dest = encodeURIComponent("Walt Disney World Resort, Orlando, FL");
  const driveUrl = `https://www.google.com/maps/dir/${origin}/${dest}/`;

  await tool.navigate({ tabId: gmapTabId, url: driveUrl });
  await tool.wait_for({ tabId: gmapTabId, condition: "load_state", value: "load", timeout_ms: 15000 });
  await tool.wait_for({ tabId: gmapTabId, condition: "dom_settled", timeout_ms: 3000 });

  const driveData = await browserjs(gmapTabId, () => {
    const text = document.body.innerText;
    // Extract first driving route
    // Look for lines like "X min\n Y miles"
    const lines = text.split("\n").map(l => l.trim()).filter(Boolean);
    let bestTime = null;
    let bestDist = null;
    let bestRouteName = null;

    for (let i = 0; i < lines.length - 2; i++) {
      if (/^\d+\s*min$/i.test(lines[i]) || /^\d+\s*hr\s*\d*\s*min$/i.test(lines[i])) {
        if (/^\d+(?:\.\d+)?\s*(?:miles|mile|mi)$/i.test(lines[i+1])) {
          bestTime = lines[i];
          bestDist = lines[i+1];
          bestRouteName = lines[i+2];
          break;
        }
      }
    }
    return { bestTime, bestDist, bestRouteName, snippet: text.slice(0, 400) };
  });

  // Check transit
  const transitUrl = `https://www.google.com/maps/dir/${origin}/${dest}/data=!4m2!4m1!3e3`;
  await tool.navigate({ tabId: gmapTabId, url: transitUrl });
  await tool.wait_for({ tabId: gmapTabId, condition: "dom_settled", timeout_ms: 3000 });

  const transitData = await browserjs(gmapTabId, () => {
    const text = document.body.innerText;
    const hasTransitNoRoute = text.includes("could not calculate transit") || text.includes("No transit routes found");
    const transitMatches = text.match(/(\d+\s*min|\d+\s*hr\s*\d*\s*min)/gi) || [];
    const busMatches = text.match(/Bus\s*\d+|Line\s*\d+|Lynx\s*\d+/gi) || [];
    return {
      hasTransit: !hasTransitNoRoute && transitMatches.length > 0,
      transitDuration: !hasTransitNoRoute && transitMatches.length > 0 ? transitMatches[0] : "No direct public transit route found",
      transitDetails: busMatches.join(", ") || (hasTransitNoRoute ? "No public transit" : "Transit available")
    };
  });

  mapResults.push({
    ...h,
    drive: driveData,
    transit: transitData,
    driveUrl
  });
}

await write("tmp://google_maps_crosscheck.json", JSON.stringify(mapResults, null, 2), "application/json");

console.log("Completed Google Maps checks for all 12 hotels:");
for (const r of mapResults) {
  console.log(`[${r.id}] ${r.name}:`);
  console.log(`   Drive: ${r.drive?.bestTime} (${r.drive?.bestDist}) via ${r.drive?.bestRouteName}`);
  console.log(`   Transit: ${r.transit?.transitDuration} | ${r.transit?.transitDetails}`);
}

